// AccessLog.java — records the URL line, exactly like a web/proxy access log
package com.nbi.web;

import java.util.*;

public class AccessLog {
    private final List<String> lines = new ArrayList<>();
    // Standard access logs capture METHOD + URL (NOT the request body).
    public void record(HttpRequest req) {
        lines.add(req.method + " " + req.url);
    }
    public List<String> lines() { return lines; }
}
