// KycHandler.java — verifies Aadhaar; masks it in the application log
package com.nbi.web;

import java.util.*;

public class KycHandler {
    private final AccessLog accessLog;
    private final List<String> appLog = new ArrayList<>();
    public KycHandler(AccessLog accessLog) { this.accessLog = accessLog; }

    public String handle(HttpRequest req) {
        accessLog.record(req); // the access log sees only method + URL
        String aadhaar;
        if ("GET".equals(req.method)) {
            // BAD: aadhaar is in the URL query string -> leaked into access log
            aadhaar = req.url.substring(req.url.indexOf("aadhaar=") + 8);
        } else {
            // GOOD: aadhaar is in the body -> NOT in the access log URL
            aadhaar = req.body.get("aadhaar");
        }
        // Mask sensitive value in application logs regardless of method.
        appLog.add("KYC verify for aadhaar=" + mask(aadhaar));
        return "VERIFIED";
    }

    private String mask(String v) {
        return v == null ? "null" : "XXXXXXXX" + v.substring(Math.max(0, v.length() - 4));
    }
    public List<String> appLog() { return appLog; }
}
