// Demo.java — contrasts GET-in-URL (leaks) vs POST-in-body (safe)
package com.nbi.web;

import java.util.*;

public class Demo {
    public static void main(String[] args) {
        AccessLog accessLog = new AccessLog();
        KycHandler handler = new KycHandler(accessLog);

        // BAD design: GET /verify?aadhaar=... (over HTTPS, but URL still logged)
        handler.handle(new HttpRequest("GET", "/verify?aadhaar=123412341234", null));

        // GOOD design: POST /verify with aadhaar in the JSON body
        handler.handle(new HttpRequest("POST", "/verify", Map.of("aadhaar", "567856785678")));

        System.out.println("ACCESS LOG (what servers/proxies record):");
        accessLog.lines().forEach(l -> System.out.println("  " + l));
        System.out.println("\nAPPLICATION LOG (sensitive value masked):");
        handler.appLog().forEach(l -> System.out.println("  " + l));
    }
}
